import React from 'react';
import { Menu, Spin } from 'antd';

const MenuInitial = ({
  dropdownKeys,
  withPropertiesOrRanges,
  selectedKey
}) => (
  <Menu.ItemGroup className='menu-item-column menu-initial'>
    {dropdownKeys ? (
      dropdownKeys.map((v) => (
        <Menu.Item
          className={v === selectedKey ? 'selected' : ''}
          key={v}
          ismainmenu='true'
        >
          {v} {v !== 'All' && withPropertiesOrRanges(v)}
        </Menu.Item>
      ))
    ) : (
      <Menu.Item disabled className="extra-features">
        <Spin />
      </Menu.Item>
    )}
  </Menu.ItemGroup>
);

export default MenuInitial;
