/* eslint-disable no-nested-ternary */
import React from 'react';
import { useDispatch, useSelector } from 'react-redux'
import {
  clone,
  isEmpty,
  isEqual,
  findLastIndex,
  isString,
  isObject,
} from 'lodash'
import { errorMessageGlobal, excludedGraphKeys, mapPageNames } from 'Utils/constants/index'
import {
  addSegmentV2,
  applySessionCustomFilter,
} from 'redux/actions/filter'
import { updateSelectedEvent } from 'redux/actions/event'
import { setActiveTab } from 'redux/actions/sessionStatistics'
import Router from 'next/router'
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder'
import { changeUrl, fetchPlanHatApi } from 'redux/actions/common'
import { trackPageViews } from 'redux/actions/trackingReport';
import { decodeUrlV2 } from 'redux/actions/megaFilter';
import ErrorBox from 'components/common/Customary/ErrorBox'
import HighchartGraph from 'components/common/Customary/HighchartGraph'
import { removeValuesFromFilters } from 'Utils/helpers/commonUtils';

const obj = {
  avg: 'averaged',
  min: 'minimized',
  max: 'maximized',
  sum: 'summed',
}
export const StatisticsGraph = ({
  graphData,
  eventDropVal,
  height,
  box_key: boxKey,
  chartRef,
  callGraphApi,
  callStatsBoxes,
}) => {
  const dispatch = useDispatch()
  const { urlReducer, appFilter, sessionStatisticsReducer } = useSelector(state => state)
  const { group_list: grpList } = sessionStatisticsReducer;
  const sessionSegment = appFilter.session.segment
  const { parentType, appId, sessionpage } = urlReducer
  const graphDataCloned = clone(graphData)
  let errorMessage
  if (eventDropVal && Object.keys(obj).includes(eventDropVal.operator)) {
    errorMessage = (
      <span style={{ textAlign: 'center' }}>
        It seems like the event property {eventDropVal.display} cannot be{' '}
        {obj[eventDropVal.operator]} in a meaningful way. <br /> Only numerical
        properties can be {obj[eventDropVal.operator]} but not strings.
      </span>
    )
  }
  if (graphDataCloned?.success) {
    !isEmpty(graphDataCloned.data.plot.series)
        graphDataCloned.data?.plot?.plotOptions?.series?.point
        ? (graphDataCloned.data.plot.plotOptions.series.point.events.click = async function urlPointer() {
          const self = this
            if ( !excludedGraphKeys.includes(self.options.name) && !excludedGraphKeys.includes(self.series.name) && self.options.y > 0) {
              if ( ( parentType === 'sessionStatistics' && self.options.url_link.includes('sessions/list') ) || ( parentType === 'aiSessionStatistics' && self.options.url_link.includes('aisessions/list') ) ) {
                const newParentType = parentType === 'aiSessionStatistics' ? 'aiSessionsList' : 'sessionsList'
                const urlD = await dispatch(decodeUrlV2(self.options.url_link))
                if (typeof urlD === 'object') {
                  if (!isEqual(urlD, sessionSegment) && urlD) {
                    await dispatch(addSegmentV2(urlD, 'session-filter'))
                    const indexBy = findLastIndex(urlD, { attribute: 'event', })
                    if (indexBy > -1) {
                      const keyObj = urlD[indexBy]
                      dispatch(updateSelectedEvent(keyObj.value))
                    }
                    callGraphApi(null, urlD)
                    callStatsBoxes(urlD)
                    dispatch(applySessionCustomFilter(1, 'session'))
                    dispatch(setActiveTab( newParentType ))
                  } else dispatch(setActiveTab( newParentType ))
                  const query = `/integration?parentType=${ newParentType }&appId=${appId}&type=session&sessionpage=${sessionpage}`
                  let url = `/app/${appId}/sessions/list/${sessionpage || 1}?`
                  
                  url = urlD.length ? urlSegmentEncoder(url, urlD) : url
                  dispatch(
                    changeUrl({
                      appId,
                      parentType: newParentType,
                      type: 'session',
                      url,
                    })
                  )
                  dispatch(
                    trackPageViews(null, {
                      eventName: 'open_list_from_chart',
                      track_type: 'event',
                      eventProperty: {
                        chartType: graphDataCloned?.data?.plot?.series[0]?.type || 'bar',
                        grouping: grpList,
                        filters: removeValuesFromFilters(sessionSegment),
                        dateRange: appFilter?.dateSegment,
                      },
                    })
                  );
                  Router.push(query, url, { shallow: true })
                }
              } else {
                window.open(self.options.url_link)
                dispatch(
                  trackPageViews(null, {
                    eventName: 'wa_plot_redirect_to_event_list',
                    track_type: 'event',
                    eventProperty: {},
                  })
                );
              }
              dispatch(fetchPlanHatApi({ action: 'Clicked on graph section', info: { page: mapPageNames[parentType] } }))
            }
          })
        : null
  }
  const isHappyFace = ['ANR_rate', 'rage_rate', 'crash_rate'].includes(boxKey)
  const titleMapper = {
    ANR_rate: 'ui freezes',
    rage_rate: 'rage taps',
    crash_rate: 'crashes',
    screen_count: 'screen visits',
    event_count: 'events',
    total_engagement: 'time in app',
  }
  
  return graphDataCloned ? (
    isObject(graphDataCloned) ? (
      graphDataCloned.success ? (
        isEmpty(graphDataCloned['data']['plot']['series']) ? (
          <ErrorBox
            displayIcon
            errorText={
              boxKey
                ? isHappyFace
                  ? `All good! We found no ${titleMapper[boxKey]} for the applied filters.`
                  : `Sorry! We found no ${titleMapper[boxKey]} for the applied filters.`
                : errorMessage || 'Graph could not be created'
            }
            isNoData
            imgSrc={isHappyFace ? '/static/icon-happy-no-data.svg' : undefined}
          />
        ) : (
          <HighchartGraph
            dataIntercomTarget="Graph"
            chartRef={chartRef}
            data={graphDataCloned.data.plot || []}
            className="graph-box-wrapper"
            id="highChart-graph"
            height={height}
          />
        )
      ) : (
        <ErrorBox displayIcon errorText={errorMessageGlobal} isNoData />
      )
    ) : (
      isString(graphDataCloned) && (
        <ErrorBox
          displayIcon
          errorText={errorMessage || graphDataCloned}
          isNoData
        />
      )
    )
  ) : (
    <div className="graph-box-wrapper" />
  )
}
export default StatisticsGraph
