/* eslint-disable no-nested-ternary */
import React, { useEffect, memo, useMemo } from 'react'
import HighchartsReact from 'highcharts-react-official'
import Highcharts from 'highcharts'
import Drilldown from 'highcharts/modules/drilldown'
import {isValid } from 'date-fns';
import { getRenamedDeviceName } from 'Utils/helpers/commonUtils';
import { useSelector } from 'react-redux';

import { formatDisplayTime, excludedGraphKeys } from "Utils/constants";
import { formatNumberWithCommas } from "Utils/helpers/numberFormatter";
import aiSessionListRedirectionHelper from 'Utils/helpers/aiSessionListRedirectionHelper';

const groupByIsHour = ['session_period_hour', 'event_period_hour']

if (typeof window !== 'undefined') {
  require('highcharts/modules/data')(Highcharts)
  require('highcharts/modules/exporting')(Highcharts)
  require('highcharts/modules/export-data')(Highcharts)
}
const HighchartGraph = (props) => {
  const { data, className, height, chartRef, dataIntercomTarget } = props;
  const { sessionStatisticsReducer:
    { group_list: sessionGroupList = [] }
    , statisticsReducer: {
      grpByVal: eventGroupList = []
    },
    urlReducer: urlQuery,
  } = useSelector((state) => state);

  const {parentType} = urlQuery;

  const groupList = [ 'sessionsList', 'aiSsessionsList' ].includes( parentType ) ? sessionGroupList : eventGroupList;

  const groupByDevice = useMemo(() => ['device_class', 'device_model'].includes(groupList[0].attribute), [groupList]);
  const groupBy = useMemo(() => groupList[0].attribute, [groupList]);

  const newData = {
    ...data,
    tooltip: {
      useHTML: true,
      formatter() {
        const { point: { color, category: date, name, y: count }, series } = this;
        const { tooltipOptions : { valueDecimals = 0 } } = series;
        const isValidDate = isValid(date);
        const formattedTitle = isValidDate ? formatDisplayTime(date, "dddd, MMM D, YYYY") : name || '';
        return `<span class="tooltipHeader">${ formattedTitle }</span>
          <div class="tooltipPointWrapper">
          <span class="tooltipLine"></span>
          <span style="color: ${color}">\u25CF</span> ${getRenamedDeviceName([series.name] || series.name)}
          <span class="tooltipPoint">: ${formatNumberWithCommas(count.toFixed(valueDecimals))}</span>`
      },
      style: {
        color: '#161E35',
      },
      backgroundColor: '#fff',
      borderRadius: 5,
      borderWidth: 1,
    },
    legend: {
      ...data.legend,
      labelFormatter() {
        const { name } = this;
        return getRenamedDeviceName(name);
      },
    },
    yAxis: {
      ...data.yAxis,
      lineColor: "#6d6875",
      lineWidth: 2,
      tickColor: "#6d6875",
      tickWidth: 2,
      gridLineColor: "#e5e5e5",
      gridLineWidth: "2",
      labels: {
        ...data.yAxis.labels,
        formatter() {
          const { value } = this;
          return data.yAxis.type === 'datetime' ? formatDisplayTime(value, "MMM D") : groupByDevice ? getRenamedDeviceName(value) : value;
        }
      }
    },
    xAxis: {
      ...data.xAxis,
      labels: {
        ...data.xAxis.labels,
        formatter() {
          const { value } = this;
          return data.xAxis.type === 'datetime'
            ? formatDisplayTime(
                value,
                groupByIsHour.includes(groupBy) ? 'MMM D, h a' : 'MMM D'
              )
            : groupByDevice
            ? getRenamedDeviceName(value)
            : value;
        }
      }
    },
    plotOptions: {
      series: {
        cursor: 'pointer',
        point: {
          events: {
            click (event) {
              const seriesData = event.point.series.options.data;
              const clickedPointData = seriesData[event.point.index];
              
              // * TARA-132  Extract URL from the data
              let url;
              if (Array.isArray(clickedPointData) && clickedPointData.length > 2) {
                  const [, , urlFromArray] = clickedPointData;
                  url = urlFromArray;
              } else if (clickedPointData.url) {
                  url = clickedPointData.url;
              } else if (event.point.options && event.point.options.url) {
                  url = event.point.options.url;
              }
              const pointName = event.point.name || event.point.options?.name;
              const seriesName = event.point.series?.name;
              if (url && !excludedGraphKeys.includes(pointName) && !excludedGraphKeys.includes(seriesName) && event.point.y > 0) {
                  const modifiedUrl = aiSessionListRedirectionHelper.modifyUrl( url );
                  window.open(modifiedUrl, '_blank');
              }
            }
          }
        }
      }
    },
     subtitle: {
      text: null   // * CX-2448: Remove subtitle text from chart
    },
  }
  useEffect(() => {
    if (!Highcharts.Chart.prototype.addSeriesAsDrilldown) {
      Drilldown(Highcharts)
    }
    const container = chartRef.current.container.current
    container.style.height = height
    chartRef.current.chart.reflow()
  }, [chartRef, data, height]);

  return (
    <div className={className} id="container" style={{ width: '100%' }} data-intercom-target={dataIntercomTarget}>
      <HighchartsReact
        highcharts={Highcharts}
        ref={chartRef}
        constructorType="chart"
        options={newData || []}
        containerProps={{ style: { height } }}
      />
    </div>
  )
}
export default memo(HighchartGraph);
