import React from 'react';
import { CloseOutlined } from '@ant-design/icons';
import { Button } from 'antd';
import classNames from 'classnames';

export const Wrapper = ({
  children,
  label,
  _idByArr: idOfArr,
  filterArr,
  _grpByArr: groupByArray,
  className = '',
  isEventProperty,
  _index: index,
  isFunnel,
  isRevamped,
  dataIntercomTarget
}) => (
  <div
    data-intercom-target={dataIntercomTarget}
    className={classNames('filter-item', {
      'button-group': isEventProperty,
      'groupby-item': idOfArr === 'grp-array' || isRevamped
    })}
  >
    <div className={`${className} combo-box`}>
      {label && isRevamped && <label>{label}</label>}
      {children}
    </div>
    {(groupByArray?.length === 2 || isFunnel) && (
      <Button
        type="close"
        onClick={() => filterArr(index)}
        icon={<CloseOutlined />}
        shape="circle"
        className={classNames({ 'funnel-groupby-btn-close': isFunnel })}
      />
    )}
  </div>
);

export default Wrapper;
